create type public.reading_status as enum ('want_to_read', 'reading', 'read');
create table public.profiles (id uuid primary key references auth.users on delete cascade, username text unique not null, display_name text not null, bio text default '', avatar_url text, created_at timestamptz default now());
create table public.books (id uuid primary key default gen_random_uuid(), google_books_id text unique, isbn text, title text not null, author text, cover_url text, page_count integer, created_at timestamptz default now());
create table public.user_books (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, book_id uuid not null references public.books on delete cascade, status public.reading_status not null, progress_percent integer default 0 check(progress_percent between 0 and 100), current_page integer default 0, updated_at timestamptz default now(), unique(user_id,book_id));
create table public.posts (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles on delete cascade, book_id uuid not null references public.books on delete cascade, body text not null check(char_length(body)<=500), progress_percent integer check(progress_percent between 0 and 100), current_page integer, rating smallint check(rating between 1 and 5), created_at timestamptz default now());
create table public.likes (user_id uuid references public.profiles on delete cascade, post_id uuid references public.posts on delete cascade, created_at timestamptz default now(), primary key(user_id,post_id));
alter table public.profiles enable row level security; alter table public.books enable row level security; alter table public.user_books enable row level security; alter table public.posts enable row level security; alter table public.likes enable row level security;
create policy "Perfis são públicos" on public.profiles for select using (true); create policy "Usuário edita seu perfil" on public.profiles for update to authenticated using ((select auth.uid())=id) with check ((select auth.uid())=id);
create policy "Livros são públicos" on public.books for select using (true); create policy "Usuários adicionam livros" on public.books for insert to authenticated with check (true);
create policy "Bibliotecas são públicas" on public.user_books for select using (true); create policy "Usuário gerencia biblioteca" on public.user_books for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "Posts são públicos" on public.posts for select using (true); create policy "Usuário cria posts" on public.posts for insert to authenticated with check ((select auth.uid())=user_id); create policy "Usuário altera posts" on public.posts for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "Usuário exclui posts" on public.posts for delete to authenticated using ((select auth.uid())=user_id);
create policy "Likes são públicos" on public.likes for select using (true); create policy "Usuário gerencia likes" on public.likes for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
